BEGIN TRANSACTION;
CREATE TABLE demo_audit(task TEXT NOT NULL REFERENCES demo_tasks(id) ON DELETE CASCADE,seq INTEGER NOT NULL,event TEXT NOT NULL,state TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(task,seq));
CREATE TABLE demo_bookings(task TEXT PRIMARY KEY REFERENCES demo_tasks(id) ON DELETE CASCADE,date TEXT NOT NULL,slot TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,UNIQUE(date,slot));
CREATE TABLE demo_decisions(owner TEXT NOT NULL REFERENCES owners(id),request TEXT NOT NULL,task TEXT NOT NULL REFERENCES demo_tasks(id) ON DELETE CASCADE,digest TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(owner,request));
CREATE TABLE demo_tasks(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES owners(id),request TEXT NOT NULL,digest TEXT NOT NULL,date TEXT NOT NULL,locale TEXT NOT NULL,state TEXT NOT NULL,version INTEGER NOT NULL,plan TEXT NOT NULL,preview TEXT,nonce_hash TEXT,expires INTEGER,receipt TEXT,created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(owner,request));
CREATE TABLE inference_usage(run TEXT PRIMARY KEY, owner TEXT NOT NULL, day TEXT NOT NULL);
CREATE TABLE memories(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES owners(id), content TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY, thread TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, seq INTEGER NOT NULL);
CREATE TABLE owners(id TEXT PRIMARY KEY);
CREATE TABLE plan_events(task TEXT NOT NULL REFERENCES task_plans(id) ON DELETE CASCADE,seq INTEGER NOT NULL,event TEXT NOT NULL,at INTEGER NOT NULL,PRIMARY KEY(task,seq));
CREATE TABLE plan_read_runs(task TEXT PRIMARY KEY REFERENCES task_plans(id) ON DELETE CASCADE,payload TEXT NOT NULL);
CREATE TABLE run_evidence(run TEXT PRIMARY KEY REFERENCES runs(id) ON DELETE CASCADE, message TEXT UNIQUE NOT NULL REFERENCES messages(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE runs(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES owners(id), thread TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE, request TEXT NOT NULL, digest TEXT NOT NULL, state TEXT NOT NULL, reply TEXT, model TEXT, UNIQUE(owner,request));
CREATE TABLE sessions(token TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES owners(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE task_plans(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES owners(id),request TEXT NOT NULL,digest TEXT NOT NULL,input TEXT NOT NULL,roles TEXT NOT NULL,state TEXT NOT NULL,pending INTEGER NOT NULL,plan TEXT,created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(owner,request));
CREATE TABLE threads(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES owners(id), agent TEXT NOT NULL, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE version (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
CREATE INDEX threads_owner ON threads(owner);
CREATE INDEX usage_day_owner ON inference_usage(day,owner);
CREATE INDEX demo_owner ON demo_tasks(owner,created);
CREATE INDEX task_plans_owner ON task_plans(owner);
COMMIT;
